func tokenizerEventLiveEnumeration(test *testing.T) (string, [][]uint16, []string, int) {
	return oracles.TokenizerEventLiveEnumeration(test)
}

func TestTokenizerEventsUnion(test *testing.T) {
	test.Parallel()
	_, inputs, names, _ := tokenizerEventLiveEnumeration(test)
	shards := tokenizerEventShards(tokenizerEventKeys(names))
	if len(shards) != testTokenizerEventsShards {
		test.Fatal("static shard count mismatch")
	}
	validateTokenizerEventUnion(test, len(inputs), shards)
}

